describe('List Item Reordering by Drag and Drop', () => {
  beforeEach(() => {
    cy.visit('/list');
  });

  it('should successfully reorder list items by dragging and dropping', () => {
    // Verify initial list order
    cy.get('[data-testid="list-item-1"]').should('be.visible');
    cy.get('[data-testid="list-item-2"]').should('be.visible');
    cy.get('[data-testid="list-item-3"]').should('be.visible');

    // Click and drag list item 2 to the top
    cy.get('[data-testid="list-item-2"]').click();
    cy.get('[data-testid="list-item-1"]').click();
    cy.get('[data-testid="list-item-2"]').click();

    // Verify list item 2 is now at the top
    cy.get('[data-testid="list-item-2"]').should('be.visible');
    cy.get('[data-testid="list-item-1"]').should('be.visible');
    cy.get('[data-testid="list-item-3"]').should('be.visible');

    // Verify list item 2 is now first
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '1');
    cy.get('[data-testid="list-item-1"]').should('have.css', 'order', '2');
    cy.get('[data-testid="list-item-3"]').should('have.css', 'order', '3');

    // Verify list item 2 has moved to the top
    cy.get('[data-testid="list-item-2"]').should('have.css', 'transform', 'translateY(0)');

    // Verify list item 1 and 3 have moved down
    cy.get('[data-testid="list-item-1"]').should('have.css', 'transform', 'translateY(100px)');
    cy.get('[data-testid="list-item-3"]').should('have.css', 'transform', 'translateY(200px)');

    // Verify list item 2 is now at the top
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '1');

    // Verify list item 1 and 3 have new positions
    cy.get('[data-testid="list-item-1"]').should('have.css', 'order', '2');
    cy.get('[data-testid="list-item-3"]').should('have.css', 'order', '3');

    // Verify list item 2 is visible and in the correct position
    cy.get('[data-testid="list-item-2"]').should('be.visible');
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '1');
  });

  it('should handle reordering when list items are dragged over each other', () => {
    // Verify initial list order
    cy.get('[data-testid="list-item-1"]').should('be.visible');
    cy.get('[data-testid="list-item-2"]').should('be.visible');
    cy.get('[data-testid="list-item-3"]').should('be.visible');

    // Click and drag list item 2 over list item 1
    cy.get('[data-testid="list-item-2"]').click();
    cy.get('[data-testid="list-item-1"]').click();
    cy.get('[data-testid="list-item-2"]').click();

    // Verify list item 2 is now between list item 1 and 3
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '2');
    cy.get('[data-testid="list-item-1"]').should('have.css', 'order', '1');
    cy.get('[data-testid="list-item-3"]').should('have.css', 'order', '3');

    // Verify list item 2 is visible and in the correct position
    cy.get('[data-testid="list-item-2"]').should('be.visible');
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '2');

    // Verify list item 1 and 3 have new positions
    cy.get('[data-testid="list-item-1"]').should('have.css', 'order', '1');
    cy.get('[data-testid="list-item-3"]').should('have.css', 'order', '3');

    // Verify list item 2 is now between list item 1 and 3
    cy.get('[data-testid="list-item-2"]').should('have.css', 'order', '2');
  });
});
